import { GetAllTransactionsResponse, GetTransactionResponse, TransactionHashResponse } from "../types/schema/transactions.js";
import { http } from "../utils/http.js";
const transactionsEndpoint = 'transactions';
/**
 * Raw HTTP calls for the `/transactions` endpoint.
 */
export async function getAllTransactions(requestOptions) {
  const response = await http(requestOptions, {
    url: transactionsEndpoint,
    responseType: 'json'
  });
  return GetAllTransactionsResponse.parse(response.data).pendingTransactions;
}
export async function getTransaction(requestOptions, hash) {
  const response = await http(requestOptions, {
    url: `${transactionsEndpoint}/${hash}`,
    responseType: 'json'
  });
  return GetTransactionResponse.parse(response.data);
}
export async function rebroadcastTransaction(requestOptions, hash) {
  const response = await http(requestOptions, {
    method: 'post',
    url: `${transactionsEndpoint}/${hash}`,
    responseType: 'json'
  });
  return TransactionHashResponse.parse(response.data).transactionHash;
}
export async function cancelTransaction(requestOptions, hash, gasPrice) {
  const headers = {};
  if (gasPrice) {
    headers['gas-price'] = gasPrice;
  }
  const response = await http(requestOptions, {
    method: 'delete',
    headers,
    url: `${transactionsEndpoint}/${hash}`,
    responseType: 'json'
  });
  return TransactionHashResponse.parse(response.data).transactionHash;
}